<?php declare(strict_types=1);
function s4r(PDO $db):array{try{return$db->query('SELECT * FROM smarttoolz_settings ORDER BY setting_key ASC')->fetchAll(PDO::FETCH_ASSOC);}catch(Throwable){return[];}}
$settings=s4r($db);
?>
<div class="av4-page"><div class="av4-stat-grid"><div class="av4-stat"><b><?=number_format(count($settings))?></b><span>Total settings</span></div><div class="av4-stat green"><b><?=number_format(count(array_filter($settings,fn($x)=>(int)($x['enabled']??0)===1)))?></b><span>Enabled</span></div><div class="av4-stat purple"><b><?=number_format(count(array_filter($settings,fn($x)=>(string)($x['setting_type']??'text')==='json'))?></b><span>JSON settings</span></div></div>
<div class="av4-card"><div class="av4-head"><div><h2>⚙️ Site Settings</h2><p>Central configuration inventory with type, value, description and status.</p></div><a class="av4-btn primary" href="/smart-toolz/admin/admin-v3.php?tab=settings">Full CRUD ↗</a></div><div class="av4-table"><table><thead><tr><th>ID</th><th>Key</th><th>Type</th><th>Value</th><th>Description</th><th>Status</th><th>Updated</th></tr></thead><tbody><?php foreach($settings as $r):?><tr><td><?=av4h($r['id']??'')?></td><td><b><?=av4h($r['setting_key']??'')?></b></td><td><span class="av4-tag purple"><?=av4h($r['setting_type']??'text')?></span></td><td class="mono"><?=av4h(substr((string)($r['setting_value']??''),0,220))?></td><td><?=av4h($r['description']??'')?></td><td><span class="av4-tag <?=!empty($r['enabled'])?'green':'gray'?>"><?=!empty($r['enabled'])?'ENABLED':'OFF'?></span></td><td><?=av4h($r['updated_at']??'')?></td></tr><?php endforeach;if(!$settings):?><tr><td colspan="7" class="empty">No settings stored.</td></tr><?php endif;?></tbody></table></div></div></div>
